B.atk=new A.as("\u0627\u0644\u062a\u0639\u0631\u0651\u0641 \u0639\u0644\u0649 \u0627\u0644\u062a\u0644\u0627\u0648\u0629 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0646\u0641\u0633\u0647 \u062f\u0648\u0646 \u0625\u0646\u062a\u0631\u0646\u062a: \u0646\u0645\u0648\u0630\u062c quran-asr-tiny (Abdou\u060c \u0631\u062e\u0635\u0629 MIT) \u2014 \u0646\u0645\u0648\u0630\u062c Conformer CTC \u0635\u063a\u064a\u0631 \u0645\u062f\u0631\u0651\u0628 \u0639\u0644\u0649 \u062a\u0644\u0627\u0648\u0627\u062a \u0627\u0644\u0645\u0635\u062d\u0641\u060c \u064a\u0643\u062a\u0628 \u0627\u0644\u062d\u0631\u0648\u0641 \u0628\u0644\u0627 \u062a\u0634\u0643\u064a\u0644\u061b \u0648\u0643\u0634\u0641 \u0627\u0644\u0643\u0644\u0627\u0645 Silero VAD (\u0631\u062e\u0635\u0629 MIT)\u061b \u0648\u0645\u062d\u0631\u0651\u0643 sherpa-onnx (\u0631\u062e\u0635\u0629 Apache-2.0). \u0644\u0627 \u064a\u064f\u0631\u0633\u0644 \u0627\u0644\u0635\u0648\u062a\u060c \u0648\u064a\u064f\u062d\u062a\u0641\u0638 \u0645\u0624\u0642\u062a\u064b\u0627 \u0641\u064a \u0627\u0644\u0630\u0627\u0643\u0631\u0629 \u0628\u0645\u0642\u0637\u0639 \u0642\u0635\u064a\u0631 \u062d\u0648\u0644 \u0643\u0644 \u062a\u0646\u0628\u064a\u0647 \u0644\u064a\u0633\u0645\u0639\u0647 \u0627\u0644\u0642\u0627\u0631\u0626 \u0641\u064a \u0627\u0644\u062a\u0642\u0631\u064a\u0631\u060c \u0648\u064a\u064f\u0645\u062d\u0649 \u0639\u0646\u062f \u0625\u063a\u0644\u0627\u0642\u0647. \u062a\u064f\u062a\u0627\u0628\u064e\u0639 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0628\u0645\u0642\u0627\u0631\u0646\u0629 \u0627\u0644\u062d\u0631\u0648\u0641 \u0627\u0644\u0645\u0633\u0645\u0648\u0639\u0629 \u0628\u062d\u0631\u0648\u0641 \u0643\u0644\u0645\u0627\u062a \u0627\u0644\u0645\u0635\u062d\u0641\u060c \u062b\u0645 \u064a\u064f\u062a\u062d\u0642\u0642 \u0645\u0646 \u0643\u0644 \u0643\u0644\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0635\u0648\u062a \u0646\u0641\u0633\u0647 \u0628\u0627\u0644\u0645\u062d\u0627\u0630\u0627\u0629 \u0627\u0644\u0642\u0633\u0631\u064a\u0629: \u0643\u0645 \u062a\u0628\u0639\u062f \u062d\u0631\u0648\u0641 \u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629 \u0639\u0645\u0651\u0627 \u0642\u064a\u0644 \u0641\u0639\u0644\u064b\u0627\u061b \u0641\u064a\u064f\u0643\u0634\u0641 \u062a\u0628\u062f\u064a\u0644 \u062d\u0631\u0641 \u0648\u0627\u062d\u062f (\u0641\u0644\u0627/\u0648\u0644\u0627\u060c \u0646\u0630\u064a\u0631/\u0646\u0643\u064a\u0631). \u0648\u0644\u0627 \u064a\u064f\u0639\u0631\u0636 \u0644\u0644\u0642\u0627\u0631\u0626 \u0625\u0644\u0627 \u0646\u0635 \u0627\u0644\u0645\u0635\u062d\u0641 \u0627\u0644\u0645\u0648\u062b\u0651\u0642. \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0645\u062f\u0631\u0651\u0628 \u0639\u0644\u0649 \u0631\u0648\u0627\u064a\u062a\u064a \u062d\u0641\u0635 \u0648\u0648\u0631\u0634 \u0644\u0627 \u0642\u0627\u0644\u0648\u0646\u060c \u0648\u0642\u062f \u062c\u064f\u0631\u0651\u0628 \u0639\u0644\u0649 \u062a\u0644\u0627\u0648\u0627\u062a \u0643\u0627\u0645\u0644\u0629 \u0628\u0631\u0648\u0627\u064a\u0629 \u0642\u0627\u0644\u0648\u0646 (\u0627\u0644\u062d\u0635\u0631\u064a\u060c \u0627\u0644\u0637\u0631\u0627\u0628\u0644\u0633\u064a\u060c \u0627\u0644\u062f\u0648\u0643\u0627\u0644\u064a \u0645\u062d\u0645\u062f \u0627\u0644\u0639\u0627\u0644\u0645) \u0641\u062a\u0627\u0628\u0639\u0647\u0627 \u0643\u0644\u0647\u0627\u060c \u0648\u0638\u0647\u0631 \u062a\u0646\u0628\u064a\u0647 \u062e\u0627\u0637\u0626 \u0639\u0644\u0649 \u0646\u062d\u0648 \u0643\u0644\u0645\u0629 \u0645\u0646 \u0643\u0644 \u0661\u0668\u0660\u061b \u0648\u0643\u0634\u0641 \u0669\u0667\u066a \u0645\u0646 \u062a\u0628\u062f\u064a\u0644\u0627\u062a \u0627\u0644\u062d\u0631\u0641 \u0627\u0644\u0648\u0627\u062d\u062f \u0641\u064a \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\u060c \u0648\xab\u0648\u0644\u0627\xbb \u0645\u0643\u0627\u0646 \xab\u0641\u0644\u0627\xbb \u0639\u0646\u062f \u062b\u0644\u0627\u062b\u0629 \u0642\u0631\u0651\u0627\u0621 \u0628\u0631\u0648\u0627\u064a\u0629 \u062d\u0641\u0635\u061b \u0648\u0645\u0639 \u0627\u0644\u0636\u062c\u064a\u062c \u0627\u0644\u0634\u062f\u064a\u062f \u0642\u062f \u064a\u0638\u0647\u0631 \u062a\u0646\u0628\u064a\u0647 \u062e\u0627\u0637\u0626 \u0639\u0644\u0649 \u0643\u0644\u0645\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0648\u0644\u0630\u0644\u0643 \u064a\u0645\u0643\u0646 \u0625\u0644\u063a\u0627\u0621 \u0623\u064a \u062a\u0646\u0628\u064a\u0647 \u0645\u0646 \u0627\u0644\u062a\u0642\u0631\u064a\u0631. \u0644\u0627 \u064a\u062a\u0639\u0631\u0651\u0641 \u0639\u0644\u0649 \u0627\u0644\u062d\u0631\u0643\u0627\u062a \u0648\u0644\u0627 \u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u062a\u062c\u0648\u064a\u062f.",null,B.e6,null,null,null,null,null,null,null,null)
