B.at1=new A.as("\u062a\u064f\u0633\u062a\u062e\u0631\u062c \u0623\u0644\u0648\u0627\u0646 \u0627\u0644\u062a\u062c\u0648\u064a\u062f \u0622\u0644\u064a\u064b\u0627 \u0645\u0646 \u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u0636\u0628\u0637 \u0641\u064a \u0646\u0635 \u0627\u0644\u0645\u062c\u0645\u0651\u0639 \u0646\u0641\u0633\u0647 \u0643\u0645\u0627 \u0634\u0631\u062d\u0647\u0627 \u0645\u0644\u062d\u0642 \xab\u0627\u0635\u0637\u0644\u0627\u062d\u0627\u062a \u0627\u0644\u0636\u0628\u0637\xbb \u0641\u064a \u0645\u0635\u062d\u0641 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0628\u0631\u0648\u0627\u064a\u0629 \u0642\u0627\u0644\u0648\u0646\u060c \u062f\u0648\u0646 \u0623\u064a \u062a\u063a\u064a\u064a\u0631 \u0641\u064a \u0627\u0644\u0646\u0635\u060c \u0648\u064a\u064f\u062a\u062d\u0642\u0642 \u0645\u0646 \u0628\u0635\u0645\u0629 \u0645\u0644\u0641 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0648\u062f\u0644\u064a\u0644\u0647 \u0639\u0646\u062f \u0643\u0644 \u062a\u0634\u063a\u064a\u0644. \u0642\u0648\u0631\u0646\u062a \u0627\u0644\u0646\u062a\u0627\u0626\u062c \u0622\u0644\u064a\u064b\u0627 \u0628\u062a\u0644\u0648\u064a\u0646 \u0631\u0648\u0627\u064a\u0629 \u062d\u0641\u0635 (quran.com) \u0641\u064a \u0627\u0644\u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u0645\u0634\u062a\u0631\u0643\u0629: \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0669\u0669\u066a\u060c \u0648\u0627\u0644\u0645\u062f\u0648\u062f \u0645\u0639 \u0627\u0644\u0647\u0645\u0632 \u0669\u0665\u066a\u060c \u0648\u0627\u0644\u063a\u0646\u0651\u0629 \u0648\u0645\u0627 \u0644\u0627 \u064a\u064f\u0644\u0641\u0638 \u0646\u062d\u0648 \u0669\u0661\u066a\u060c \u0648\u0645\u0627 \u0627\u062e\u062a\u0644\u0641 \u0643\u0627\u0646 \u0645\u0646 \u0641\u0631\u0648\u0642 \u0627\u0644\u0631\u0648\u0627\u064a\u062a\u064a\u0646 \u0623\u0648 \u0645\u0646 \u0645\u0648\u0636\u0639 \u0627\u0644\u062a\u0644\u0648\u064a\u0646. \u0648\u062f\u0644\u064a\u0644 \u0627\u0644\u0623\u062d\u0643\u0627\u0645 \u062a\u0644\u062e\u064a\u0635 \u0645\u0646 \u0645\u0644\u062d\u0642 \u0645\u0635\u062d\u0641 \u0627\u0644\u0645\u062c\u0645\u0651\u0639 \u0648\u0645\u0646 \u0643\u062a\u0627\u0628 \xab\u0643\u064a\u0641 \u062a\u0642\u0631\u0623 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u0628\u0631\u0648\u0627\u064a\u0629 \u0627\u0644\u0625\u0645\u0627\u0645 \u0642\u0627\u0644\u0648\u0646 \u0639\u0646 \u0646\u0627\u0641\u0639 \u0627\u0644\u0645\u062f\u0646\u064a\xbb \u0644\u0644\u0645\u062e\u062a\u0627\u0631 \u0627\u0644\u0645\u0642\u0631\u0648\u0634\u060c \u0645\u0639 \u0630\u0643\u0631 \u0627\u0644\u0645\u0635\u062f\u0631 \u0639\u0646\u062f \u0643\u0644 \u062d\u0643\u0645\u061b \u0648\u0644\u0627 \u064a\u063a\u0646\u064a \u0639\u0646 \u0627\u0644\u062a\u0644\u0642\u0651\u064a \u0645\u0646 \u0634\u064a\u062e.",null,B.e6,null,null,null,null,null,null,null,null)
